import 'package:ciwapa_core/ciwapa_core.dart';

import 'frontend.dart';

/// The generated host.dart: the program's own data, handed to the Interstates host.
String dartHost(IrProgram program) {
  final data = program.extension as InterstatesProgram;
  final out = StringBuffer(
    '// Generated by ioi-dart. Do not edit.\n'
    "import 'ioi_host.dart';\n"
    "import 'runtime.dart';\n\n"
    'IckHost createHost() => IoiHost(\n'
    '  routes: const [\n',
  );
  for (final r in data.routes.routes) {
    final segments = r.segments == null
        ? 'null'
        : '[${r.segments!.map((s) => s.text == null ? 'null' : _dartString(s.text!)).join(', ')}]';
    final allowed = r.restricted ? '[${r.allowed.join(', ')}]' : 'null';
    out.writeln('    IoiRoute(${r.ordinal}, $segments, $allowed),');
  }
  out.write('  ],\n);\n');
  return out.toString();
}

String _dartString(String s) {
  final escaped = s
      .replaceAll(r'\', r'\\')
      .replaceAll("'", r"\'")
      .replaceAll(r'$', r'\$')
      .replaceAll('\n', r'\n')
      .replaceAll('\r', r'\r');
  return "'$escaped'";
}

/// The program's own data for host.c, appended to it: the definitions of what it declares
/// `extern`.
String cHostData(IrProgram program) {
  final data = program.extension as InterstatesProgram;
  final out = StringBuffer(
    '\n/* ---- Generated by ioi-llvm for this program. ---- */\n',
  );
  final routes = <String>[];
  for (final (i, r) in data.routes.routes.indexed) {
    var segments = 'NULL';
    if (r.segments case final list?) {
      final parts = <String>[];
      for (final (j, s) in list.indexed) {
        final text = s.text;
        if (text == null) {
          parts.add('{NULL, -1}');
        } else if (text.isEmpty) {
          parts.add('{NULL, 0}');
        } else {
          out.writeln(
            'static const uint16_t ioi_text_${i}_$j[] = {${text.codeUnits.join(', ')}};',
          );
          parts.add('{ioi_text_${i}_$j, ${text.codeUnits.length}}');
        }
      }
      out.writeln(
        'static const ioi_segment ioi_route_$i[] = {${parts.join(', ')}};',
      );
      segments = 'ioi_route_$i';
    }
    var allowed = 'NULL';
    if (r.restricted && r.allowed.isNotEmpty) {
      out.writeln(
        'static const uint32_t ioi_allowed_$i[] = {${r.allowed.join(', ')}};',
      );
      allowed = 'ioi_allowed_$i';
    }
    routes.add(
      '{$segments, ${r.segments?.length ?? -1}, ${r.ordinal}, '
      '${r.restricted ? r.allowed.length : -1}, $allowed}',
    );
  }
  out
    ..writeln(
      'const ioi_route ioi_routes[] = {${routes.isEmpty ? '{0}' : routes.join(', ')}};',
    )
    ..writeln('const uint32_t ioi_route_count = ${routes.length};');
  return out.toString();
}
